**Example 1: Plugin Manifest (plugin.json)**

```json
{
  "pluginId": "com.gainwell.medicaid.statea.claims",
  "name": "State A Claims Processing Plugin",
  "version": "2.1.0",
  "description": "State-specific claims processing rules for State A Medicaid",
  "author": "Gainwell DDI Team - State A",
  "productCompatibility": {
    "minimumVersion": "5.0.0",
    "maximumVersion": "6.0.0"
  },
  "ipOwnership": "StateExclusive",
  "tenantId": "state-a",
  "extensionPoints": [
    "ClaimsProcessing.PreValidation",
    "ClaimsProcessing.PostAdjudication"
  ],
  "dependencies": [
    {
      "name": "Gainwell.Claims.Core",
      "version": "5.2.0"
    }
  ],
  "configuration": {
    "settingsSchema": "schemas/claims-config-schema.json",
    "defaultSettings": {
      "enableAdvancedValidation": true,
      "maxRetries": 3
    }
  }
}
```

**Example 2: Plugin Implementation**

```csharp
using Gainwell.Extensions.PluginSDK;
using Gainwell.Claims.Core;

[Plugin("com.gainwell.medicaid.statea.claims")]
public class StateAClaimsPlugin : PluginBase
{
    private readonly IClaimsValidator _validator;
    private readonly IStateARulesEngine _rulesEngine;

    public override string PluginId => "com.gainwell.medicaid.statea.claims";
    public override string Name => "State A Claims Processing";
    public override Version Version => new Version(2, 1, 0);

    public StateAClaimsPlugin(
        IClaimsValidator validator,
        IStateARulesEngine rulesEngine)
    {
        _validator = validator;
        _rulesEngine = rulesEngine;
    }

    protected override async Task OnInitializeAsync(IPluginContext context)
    {
        // Load state-specific rules
        await _rulesEngine.LoadRulesAsync(context.Configuration);
        Logger.LogInformation("State A Claims Plugin initialized");
    }

    public override async Task<PluginResult> ExecuteAsync(IExecutionContext executionContext)
    {
        var claim = executionContext.GetData<Claim>("claim");

        // Apply State A specific validation
        var validationResult = await _validator.ValidateAsync(claim);
        if (!validationResult.IsValid)
        {
            return PluginResult.Failure(validationResult.Errors);
        }

        // Apply State A specific business rules
        var ruleResult = await _rulesEngine.ApplyRulesAsync(claim);

        return PluginResult.Success(new
        {
            ValidationPassed = true,
            RulesApplied = ruleResult.AppliedRules,
            ModifiedClaim = ruleResult.ProcessedClaim
        });
    }

    public override void Dispose()
    {
        _rulesEngine?.Dispose();
        base.Dispose();
    }
}
```

**Example 3: Registering Plugin in DI Container**

```csharp
public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        // Register Plugin Infrastructure
        services.AddSingleton<IPluginHost, PluginHost>();
        services.AddSingleton<IPluginRegistry, PluginRegistry>();
        services.AddScoped<IPluginLoader, PluginLoader>();

        // Configure Plugin Discovery
        services.Configure<PluginOptions>(Configuration.GetSection("PluginConfiguration"));

        // Register Plugin Services
        services.AddTransient<IClaimsValidator, ClaimsValidator>();
        services.AddTransient<IStateARulesEngine, StateARulesEngine>();
    }

    public void Configure(IApplicationBuilder app)
    {
        // Initialize Plugin Host
        var pluginHost = app.ApplicationServices.GetRequiredService<IPluginHost>();
        pluginHost.InitializeAsync().Wait();

        // Register health checks
        app.UseHealthChecks("/health", new HealthCheckOptions
        {
            ResponseWriter = UIResponseWriter.WriteHealthCheckUIResponse
        });
    }
}
```

